package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderAccountLinkPolicyOptions;

class AccountLinkPolicyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property account link policy of tenant login provider ")
  void test_account_link_policy_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AccountLinkPolicyVO.tryFrom("_NONE_"));
    Assertions.assertEquals(TenantLoginProviderAccountLinkPolicyOptions.NONE,
        AccountLinkPolicyVO.tryFrom("NONE").getAccountLinkPolicy());
    Assertions.assertThrows(ConstraintException.class, () -> AccountLinkPolicyVO.tryFrom(null));
    Assertions.assertEquals(TenantLoginProviderAccountLinkPolicyOptions.NONE, AccountLinkPolicyVO
        .from(TenantLoginProviderAccountLinkPolicyOptions.NONE).getAccountLinkPolicy());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AccountLinkPolicyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + TenantLoginProviderAccountLinkPolicyOptions.NONE + "]",
        AccountLinkPolicyVO.from(TenantLoginProviderAccountLinkPolicyOptions.NONE).toString());
  }
}
